package youtubewebmock

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// The corpus is generated by `moon run youtube-web-mock:generate-fixtures`.
const generatedTopologies = "fixtures/youtube"

func TestGeneratedCorpusStartsTheMock(t *testing.T) {
	t.Parallel()
	mock, err := Start(t.Context(), Config{
		Address:          "127.0.0.1:0",
		CAFile:           filepath.Join(t.TempDir(), "ca.pem"),
		FixtureDirectory: generatedTopologies,
	})
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.WithoutCancel(t.Context()), 5*time.Second)
	defer cancel()
	if err := mock.Close(ctx); err != nil {
		t.Fatal(err)
	}
}

func TestGeneratedSourcesAreServable(t *testing.T) {
	t.Parallel()
	entries, err := os.ReadDir(filepath.Dir(generatedTopologies))
	if err != nil {
		t.Fatal(err)
	}
	server := &Server{fixtures: generatedTopologies}
	served := 0
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		if _, err := server.sourceFixturePath(entry.Name()); err != nil {
			t.Errorf("generated source %s is not servable: %v", entry.Name(), err)
		}
		served++
	}
	if served == 0 {
		t.Fatal("no generated source videos")
	}
}
